<template><view class="page"><view class="wrap"><MobileHeader title="账户与连接" back-icon-name="chevron-left"/><view v-if="session.identity" class="card"><view class="row"><text>当前账户</text><text>{{session.identity.user.nickname}}</text></view><button class="primary" :disabled="busy" @tap="logout">退出登录</button></view><view v-else class="card"><view class="field"><text>账号</text><input v-model="username" placeholder="请输入账号" autocomplete="username"/></view><view class="field"><text>密码</text><input v-model="password" password placeholder="请输入密码"/></view><button class="primary" :disabled="busy" @tap="login">{{busy?'正在登录…':'登录'}}</button></view><view class="card"><view class="field"><text>服务器</text><input v-model="address" placeholder="留空使用同源服务"/></view><view class="field"><text>工作区编号</text><input v-model="tenant" placeholder="请输入工作区编号"/></view><button class="primary" @tap="save">保存连接</button></view><text class="error">{{error}}</text></view></view></template>
<script setup lang="ts">import {ref} from 'vue';import MobileHeader from '@/components/MobileHeader.vue';import {client,session,settings,saveSettings,signIn,signOut} from '@/platform';import {logger} from '@/services/logger';const username=ref(''),password=ref(''),address=ref(settings.baseUrl),tenant=ref(settings.tenantId),busy=ref(false),error=ref('');async function login(){if(!username.value||!password.value){error.value='请输入账号和密码';return;}busy.value=true;error.value='';try{await signIn(username.value,password.value);password.value='';logger.info('auth','login.succeeded');uni.reLaunch({url:'/pages/index/index'});}catch{session.identity=client.identity;error.value='登录失败，请核对账号、密码和服务器';}finally{busy.value=false;}}async function logout(){busy.value=true;try{await signOut();password.value='';}finally{busy.value=false;}}function save(){try{saveSettings(address.value,tenant.value);session.identity=null;uni.reLaunch({url:'/pages/index/index'});uni.showToast({title:'连接已保存，请重新登录',icon:'none'});}catch{error.value='连接设置无效';}}</script>
<style scoped lang="scss">.page{min-height:100vh;background:#f7f8fc;padding-bottom:calc(110px + env(safe-area-inset-bottom))}.wrap{max-width:500px;margin:auto;padding:0 15px}.section-title{font-size:17px;font-weight:600}.card{background:#fff;border-radius:18px;padding:18px;margin-top:14px;box-shadow:0 6px 16px rgba(20,31,51,.06)}.row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:14px 0;border-bottom:1px solid #eef1f6}.row:last-child{border:0}.muted{color:#8791a4;font-size:12px}.primary{margin-top:20px;background:#294fdb;color:white;border-radius:12px;font-size:14px}.field{padding:15px 0;border-bottom:1px solid #eef1f6}.field text{display:block;font-size:13px;color:#636e82;margin-bottom:10px}.field input{font-size:14px}.empty{padding:36px 0;text-align:center;color:#8791a4;font-size:14px}.badge{color:#294fdb;font-size:12px}.error{color:#d44545;font-size:13px;margin-top:12px}</style>
